  const paths={feet:'M8 4h11v13l7 4v6H5v-8h3z',chest:'M9 4 4 8l3 8 4-2v13h10V14l4 2 3-8-5-4-4 4h-6z',legs:'M7 5h18v22h-7l-2-13-2 13H7z',head:'M5 18v-5a11 11 0 0 1 22 0v5l-5 3v7l-6-3-6 3v-7z'};
  const path=item.iconPath||paths[item.slot];
  const image=path?`<svg width='38' height='38' viewBox='0 0 32 32' aria-hidden='true'><path d='${esc(path)}' fill='#bba47b' stroke='#f5d79d' stroke-width='1'/></svg>`:`<span aria-hidden='true'>?</span>`;
  const material={cloth:'Ткань',leather:'Кожа',mail:'Кольчуга',plate:'Латы'}[item.armorType||String(item.questProfile||'').split(':')[0]];
  const stats=[['armorFlat','Броня'],['stamina','Выносливость'],['strength','Сила'],['agility','Ловкость'],['intellect','Интеллект']].filter(pair=>item[pair[0]]).map(pair=>pair[1]+' +'+item[pair[0]]);
  const detail=[material,item.label,item.requiredLevel?'Требуется уровень '+item.requiredLevel:''].filter(Boolean).join(' · ');
  return `<div class='az-item-receipt' style='display:grid;grid-template-columns:56px minmax(0,1fr);gap:12px;align-items:start;padding:12px;margin:8px 0;background:#191c20;border:1px solid #635b4b;border-radius:7px;color:#f5ead4;text-align:left;box-sizing:border-box;max-width:100%'><span style='position:relative;display:grid;place-items:center;box-sizing:border-box;width:56px;height:56px;background:#101215;border:2px solid ${color};border-radius:5px;box-shadow:inset 0 0 0 2px #0008;color:#f5ead4'>${image}<small style='position:absolute;right:2px;bottom:1px;padding:0 3px;background:#101215;color:#fff;font-size:12px;line-height:16px'>×${esc(String(count))}</small></span><span style='min-width:0;overflow-wrap:anywhere'><strong style='display:block;color:${color};font-size:1rem;line-height:1.35;text-shadow:none;margin:0 0 4px'>${esc(item.name)}</strong><small style='display:block;color:#ded4c0;line-height:1.4'>${esc(detail)}</small><small style='display:block;color:#ded4c0;line-height:1.4'>${esc(stats.join(' · '))}</small></span></div>`;
}
